/**
 * Device config for internal user auto login. Only one config per device is stored.
 */
export class DeviceConfig implements CredentialsStorage, UsageTestStorage {
	static readonly Version = 3
	static readonly LocalStorageKey = "tutanotaConfig"

	private config: Config
	private lastStoredConfig: string | null = null

	constructor(
		private readonly version: number = DeviceConfig.Version,
		private readonly storage: ConfigStorage | null = availableStorage(),
		private readonly storageKey: string = DeviceConfig.LocalStorageKey,
	) {
		this.config = this.defaultConfig()
		this._load()
	}

	private defaultConfig(): Config {
		return {
			_version: this.version,
			_credentials: new Map(),
			_scheduledAlarmUsers: [],
			_themeId: defaultThemeId,
			_language: null,
			_defaultCalendarView: {},
			_hiddenCalendars: {},
			_signupToken: "",
			_credentialEncryptionMode: null,
			_encryptedCredentialsKey: null,
			_testDeviceId: null,
			_testAssignments: null,
		}
	}

	store(persistentCredentials: PersistentCredentials): void {

		const existing = this.config._credentials.get(persistentCredentials.credentialInfo.userId)

		if (existing?.databaseKey) {
			persistentCredentials.databaseKey = existing.databaseKey
		}

		this.config._credentials.set(persistentCredentials.credentialInfo.userId, persistentCredentials)

		this._writeToStorage()
	}

	loadByUserId(userId: Id): PersistentCredentials | null {
		return this.config._credentials.get(userId) ?? null
	}

	loadAll(): Array<PersistentCredentials> {
		return Array.from(this.config._credentials.values())
	}

	deleteByUserId(userId: Id): void {
		this.config._credentials.delete(userId)

		this._writeToStorage()
	}

	_load(): void {
		let loadedConfig: any | null = null
		try {
			const loadedConfigString = this.storage?.getItem(this.storageKey)
			loadedConfig = loadedConfigString != null ? this._parseConfig(loadedConfigString) : null
		} catch (e) {
			console.warn("Could not load device config", e)
		}

		const migrated = loadedConfig != null && migrateConfig(loadedConfig, this.version)
		const defaults = this.defaultConfig()
		this.config = loadedConfig == null ? defaults : {
			_version: typeof loadedConfig._version === "number" ? loadedConfig._version : defaults._version,
			_credentials: deserializeCredentials(loadedConfig._credentials),
			_scheduledAlarmUsers: Array.isArray(loadedConfig._scheduledAlarmUsers) ? loadedConfig._scheduledAlarmUsers : defaults._scheduledAlarmUsers,
			_themeId: loadedConfig._themeId ?? defaults._themeId,
			_language: loadedConfig._language ?? defaults._language,
			_defaultCalendarView: loadedConfig._defaultCalendarView ?? defaults._defaultCalendarView,
			_hiddenCalendars: loadedConfig._hiddenCalendars ?? defaults._hiddenCalendars,
			_signupToken: loadedConfig._signupToken ?? defaults._signupToken,
			_credentialEncryptionMode: loadedConfig._credentialEncryptionMode ?? defaults._credentialEncryptionMode,
			_encryptedCredentialsKey: loadedConfig._encryptedCredentialsKey ?? defaults._encryptedCredentialsKey,
			_testDeviceId: loadedConfig._testDeviceId ?? defaults._testDeviceId,
			_testAssignments: loadedConfig._testAssignments ?? defaults._testAssignments,
