			return key === "_credentials" ? Object.fromEntries(this.config._credentials) : value
		})
	}

	_writeToStorage() {
		const serialized = this.serializeConfig()
		if (serialized === this.lastStoredConfig || this.storage == null) {
			return
		}

		try {
			this.storage.setItem(this.storageKey, serialized)
			this.lastStoredConfig = serialized
		} catch (e) {
			// may occur in Safari < 11 in incognito mode because it throws a QuotaExceededError
			// DOMException will occurr if all cookies are disabled
			console.log("could not store config", e)
		}
	}

	getTheme(): ThemeId {
		return this.config._themeId
	}

	setTheme(theme: ThemeId) {
		if (this.config._themeId !== theme) {
			this.config._themeId = theme

			this._writeToStorage()
		}
	}

	getDefaultCalendarView(userId: Id): CalendarViewType | null {
		return this.config._defaultCalendarView[userId] ?? null
	}

	setDefaultCalendarView(userId: Id, defaultView: CalendarViewType) {
		if (this.config._defaultCalendarView[userId] !== defaultView) {
			this.config._defaultCalendarView[userId] = defaultView

			this._writeToStorage()
		}
	}

	getHiddenCalendars(user: Id): Id[] {
		return Object.prototype.hasOwnProperty.call(this.config._hiddenCalendars, user) ? this.config._hiddenCalendars[user] : []
	}

	setHiddenCalendars(user: Id, calendars: Id[]) {
		if (this.config._hiddenCalendars[user] !== calendars) {
			this.config._hiddenCalendars[user] = calendars

			this._writeToStorage()
		}
	}

	getCredentialEncryptionMode(): CredentialEncryptionMode | null {
		return this.config._credentialEncryptionMode
	}

	setCredentialEncryptionMode(encryptionMode: CredentialEncryptionMode | null) {
		this.config._credentialEncryptionMode = encryptionMode

		this._writeToStorage()
	}

	getCredentialsEncryptionKey(): Uint8Array | null {
		return this.config._encryptedCredentialsKey ? base64ToUint8Array(this.config._encryptedCredentialsKey) : null
	}

	setCredentialsEncryptionKey(value: Uint8Array | null) {
		if (value) {
			this.config._encryptedCredentialsKey = uint8ArrayToBase64(value)
		} else {
			this.config._encryptedCredentialsKey = null
		}

		this._writeToStorage()
	}

	async getTestDeviceId(): Promise<string | null> {
		return this.config._testDeviceId
	}

	async storeTestDeviceId(testDeviceId: string): Promise<void> {
		this.config._testDeviceId = testDeviceId
		this._writeToStorage()
	}

	async getAssignments(): Promise<PersistedAssignmentData | null> {
		return this.config._testAssignments
	}

	async storeAssignments(persistedAssignmentData: PersistedAssignmentData): Promise<void> {
		this.config._testAssignments = persistedAssignmentData
		this._writeToStorage()
	}
}


function deserializeCredentials(credentials: any): Map<Id, PersistentCredentials> {
	if (credentials == null || typeof credentials !== "object" || Array.isArray(credentials)) {
		return new Map()
	}
	return new Map(Object.entries(credentials) as Array<[Id, PersistentCredentials]>)
}

function createSignupToken(): string {
	const bytes = new Uint8Array(6)
	const availableCrypto = typeof globalThis.crypto !== "undefined" ? globalThis.crypto : typeof window !== "undefined" ? window.crypto : null
	if (availableCrypto?.getRandomValues) {
		availableCrypto.getRandomValues(bytes)
	} else {
		for (let i = 0; i < bytes.length; i++) {
			bytes[i] = Math.floor(Math.random() * 256)
		}
	}
	return uint8ArrayToBase64(bytes)
}

/** Updates a stored config in place and reports whether it changed. */
export function migrateConfig(loadedConfig: any, version: number = DeviceConfig.Version): boolean {
	if (loadedConfig._version > version) {
		return false
	}

	let changed = false
	if (version >= 3 && Array.isArray(loadedConfig._credentials)) {
		migrateConfigV2to3(loadedConfig)
		changed = true
	}

	if (loadedConfig._credentials == null) {
		loadedConfig._credentials = {}
		changed = true
	}

	if (loadedConfig._version !== version) {
		loadedConfig._version = version
		changed = true
	}

	return changed
}

/**
 * Migrate from V2 of the config to V3
 *
 * Exported for testing
 */
export function migrateConfigV2to3(loadedConfig: any) {
	if (!Array.isArray(loadedConfig._credentials)) {
		return
	}

	const credentials: Record<Id, PersistentCredentials> = {}
	for (const oldCredential of loadedConfig._credentials) {
		if (oldCredential == null || typeof oldCredential !== "object") {
			continue
		}

		const userId = oldCredential.credentialInfo?.userId ?? oldCredential.userId
		if (typeof userId !== "string") {
			continue
		}

		if (oldCredential.credentialInfo != null) {
			credentials[userId] = {...oldCredential, databaseKey: oldCredential.databaseKey ?? null}
		} else {
			const hasEmailAddress = typeof oldCredential.mailAddress === "string" && oldCredential.mailAddress.includes("@")
			credentials[userId] = {
				credentialInfo: {
					login: hasEmailAddress ? oldCredential.mailAddress : userId,
					userId,
					type: hasEmailAddress ? "internal" : "external",
				},
				encryptedPassword: oldCredential.encryptedPassword,
				accessToken: oldCredential.accessToken,
				databaseKey: oldCredential.databaseKey ?? null,
			}
		}
	}
	loadedConfig._credentials = credentials
}

