o.spec("DeviceConfig", function () {
	o("keeps current-version storage unchanged on load and deserializes credentials", async function () {
		const persisted = completeConfig()
		const originalJson = JSON.stringify(persisted)
		const storage = memoryStorage(originalJson)

		const config = new DeviceConfig(DeviceConfig.Version, storage)

		o(storage.writes.length).equals(0)
		o(storage.value()).equals(originalJson)
		o(config.loadByUserId("userId")!).deepEquals(persisted._credentials.userId)
		o(config.loadAll()).deepEquals([persisted._credentials.userId])
		o(config.getSignupToken()).equals(persisted._signupToken)
		o(config.getTheme()).equals(persisted._themeId)
		o(config.getLanguage()).equals(persisted._language)
		o(config.hasScheduledAlarmsForUser("userId")).equals(true)
		o(config.getDefaultCalendarView("userId")).equals(persisted._defaultCalendarView.userId)
		o(config.getHiddenCalendars("userId")).deepEquals(persisted._hiddenCalendars.userId)
		o(config.getCredentialEncryptionMode()).equals(persisted._credentialEncryptionMode)
		o(Array.from(config.getCredentialsEncryptionKey()!)).deepEquals([107, 101, 121])
		o(await config.getTestDeviceId()).equals(persisted._testDeviceId)
		o((await config.getAssignments())!).deepEquals(persisted._testAssignments)
	})

	o("writes once when a signup token is missing and preserves every stored field", function () {
		const persisted: any = completeConfig()
		delete persisted._signupToken
		const storage = memoryStorage(JSON.stringify(persisted))

		const config = new DeviceConfig(DeviceConfig.Version, storage)
		const saved = JSON.parse(storage.value()!)

		o(storage.writes.length).equals(1)
		o(storage.writes[0].key).equals(DeviceConfig.LocalStorageKey)
		o(config.getSignupToken()).equals(saved._signupToken)
		o(saved._signupToken.length).equals(8)
		for (const [key, value] of Object.entries(persisted)) {
			o(saved[key]).deepEquals(value)
		}
	})

	o("does not write current-version storage with a token when credentials are absent", function () {
		const persisted: any = completeConfig()
		delete persisted._credentials
		const originalJson = JSON.stringify(persisted)
		const storage = memoryStorage(originalJson)

		const config = new DeviceConfig(DeviceConfig.Version, storage)

		o(config.loadAll()).deepEquals([])
		o(storage.writes.length).equals(0)
		o(storage.value()).equals(originalJson)
	})

	o("keeps the database key when credentials are updated", function () {
		const storage = memoryStorage(JSON.stringify(completeConfig()))
		const config = new DeviceConfig(DeviceConfig.Version, storage)
		const updated: PersistentCredentials = {
			credentialInfo: {login: "new@example.com", userId: "userId", type: "internal"},
			accessToken: "newAccessToken",
			encryptedPassword: "newEncryptedPassword",
			databaseKey: null,
		}

		config.store(updated)

		o(config.loadByUserId("userId")?.databaseKey).equals("databaseKey")
		o(JSON.parse(storage.value()!)._credentials.userId.databaseKey).equals("databaseKey")
		o(storage.writes.length).equals(1)
	})

	o("does not write when a setter leaves persisted data unchanged", function () {
		const storage = memoryStorage(JSON.stringify(completeConfig()))
		const config = new DeviceConfig(DeviceConfig.Version, storage)

		config.setLanguage("de")
		config.setAlarmsScheduledForUser("userId", true)
		config.store(config.loadByUserId("userId")!)

		o(storage.writes.length).equals(0)
	})

	o("recovers from invalid JSON with a valid persisted config", function () {
		const storage = memoryStorage("{broken")

		const config = new DeviceConfig(DeviceConfig.Version, storage)
		const saved = JSON.parse(storage.value()!)

		o(storage.writes.length).equals(1)
		o(saved._version).equals(DeviceConfig.Version)
		o(saved._credentials).deepEquals({})
		o(saved._signupToken).equals(config.getSignupToken())
	})

	o("recovers when reading storage throws", function () {
		const storage = {
			getItem(_key: string): string | null {
			getItem(_key: string): string | null {
				throw new Error("storage unavailable")
			},
			setItem(_key: string, _value: string): void {
				throw new Error("storage unavailable")
			},
		}

		const config = new DeviceConfig(DeviceConfig.Version, storage)

		o(config.getSignupToken().length).equals(8)
		o(config.loadAll()).deepEquals([])
	})

	o.spec("migrateConfigV2to3", function () {
		o("converts legacy credentials to a userId-keyed object", function () {
			const oldConfig: any = {
				_version: 2,
				_credentials: [
					{
						mailAddress: "internal@example.com",
						userId: "internalUserId",
						accessToken: "internalAccessToken",
						encryptedPassword: "internalEncPassword",
					},
					{
						mailAddress: "externalUserId",
						userId: "externalUserId",
						accessToken: "externalAccessToken",
						encryptedPassword: "externalEncPassword",
					},
				],
			}

			migrateConfigV2to3(oldConfig)

			o(Object.keys(oldConfig._credentials)).deepEquals(["internalUserId", "externalUserId"])
			o(oldConfig._credentials.internalUserId.credentialInfo).deepEquals({
				login: "internal@example.com",
				userId: "internalUserId",
				type: "internal",
			})
			o(oldConfig._credentials.externalUserId.credentialInfo).deepEquals({
				login: "externalUserId",
				userId: "externalUserId",
				type: "external",
			})
			o(oldConfig._credentials.internalUserId.accessToken).equals("internalAccessToken")
			o(oldConfig._credentials.externalUserId.encryptedPassword).equals("externalEncPassword")
		})
	})

	o("migrates once, preserving other underscored fields", function () {
		const legacy: any = completeConfig()
		legacy._version = 2
		legacy._credentials = [{
			mailAddress: "user@example.com",
			userId: "userId",
			accessToken: "accessToken",
			encryptedPassword: "encryptedPassword",
		}]
		const storage = memoryStorage(JSON.stringify(legacy))

		const first = new DeviceConfig(DeviceConfig.Version, storage)
		const saved = JSON.parse(storage.value()!)

		o(storage.writes.length).equals(1)
		o(saved._version).equals(DeviceConfig.Version)
		o(saved._credentials.userId.credentialInfo.type).equals("internal")
		o(first.loadByUserId("userId")?.accessToken).equals("accessToken")
		for (const [key, value] of Object.entries(legacy)) {
			if (key !== "_version" && key !== "_credentials") {
				o(saved[key]).deepEquals(value)
			}
		}

		new DeviceConfig(DeviceConfig.Version, storage)
		o(storage.writes.length).equals(1)
	})
})

